actions.action:
def created = []
def unchanged = []
def failed = []

def faktura = "schvalovanie/faktury/fa_faktura"
def objednavka = "schvalovanie/objednavky/ob_objednavka"
def vsetkyF = "processIdentifier:\"" + faktura + "\""
// Kazda appka ma vlastny priecinok: karta "Objednávky a faktúry" je rodic
// a pod nou su dva uzly. Uzol vznikne importom siete, ktorej identifikator tu
// cestu nesie (`schvalovanie/faktury/fa_faktura`), takze poradie v manifeste
// zalezi. Nazvy priecinkov v bocnom menu su `uriNode.*` v assets/i18n.
def uriF = "schvalovanie/faktury"
def uriO = "schvalovanie/objednavky"
def vsetkyO = "processIdentifier:\"" + objednavka + "\""

// Predvolene stlpce zoznamu. Su to `HeaderColumn.uniqueId` oddelene ciarkou:
// meta stlpec je `meta-<pole>`, datove pole je `<identifikator siete>-<id pola>`
// a MUSI mat immediate="true", inak sa do casu ani do indexu nedostane
// a stlpec zostane prazdny.
// `-fa_ceka_na` je stlpec "U koho lezi". Bez neho zadavatel v zozname
// nezistil, kto ma jeho fakturu na stole - stav povie "Caka na stredisko",
// ale nie na kom to visi. Pole nesie MENA (nie roly), aby stlpec fungoval
// v oboch jazykoch.
def stlpceF = "meta-title" +
        ",schvalovanie/faktury/fa_faktura-fa_stav_label" +
        ",schvalovanie/faktury/fa_faktura-fa_ceka_na" +
        ",schvalovanie/faktury/fa_faktura-fa_dodavatel" +
        ",schvalovanie/faktury/fa_faktura-fa_suma" +
        ",schvalovanie/faktury/fa_faktura-fa_datum_splatnosti"
def stlpceO = "meta-title" +
        ",schvalovanie/objednavky/ob_objednavka-ob_stav_label" +
        ",schvalovanie/objednavky/ob_objednavka-ob_ceka_na" +
        ",schvalovanie/objednavky/ob_objednavka-ob_suma" +
        ",schvalovanie/objednavky/ob_objednavka-ob_termin"

def views = [
        // --- Faktury ---
        [id: "sc_fa_vsetky", name: i18n("Došlé faktúry", ["en": "Incoming invoices"]),
         type: "Case", icon: "receipt_long",
         query: vsetkyF, nets: [faktura], roles: [:], headers: stlpceF, uri: uriF],
        // Nazov nesie slovo "faktúry" zamerne: dovolenky maju zobrazenie
        // "Rozpísané a vrátené" tiez a na dashboarde su karty vedla seba bez
        // priecinka, takze dve rovnako pomenovane sa nedaju odlisit.
        [id: "sc_fa_rozpisane",
         name: i18n("Rozpísané faktúry", ["en": "Draft invoices"]),
         type: "Case", icon: "edit_note",
         query: vsetkyF + " AND taskIds:\"t_fa_zapis\"",
         nets: [faktura], roles: [:], headers: stlpceF, uri: uriF],
        // Obe urovne schvalenia v jednej fronte: kto ma na fakture co robit,
        // vidi ju tu, a co presne moze, riadi `perform` na prechode. Dve
        // polozky by znamenali, ze schvalovatel ma v menu jednu, ktora je pre
        // neho vzdy prazdna.
        [id: "sc_fa_na_schvalenie", name: i18n("Faktúry na schválenie", ["en": "Invoices to approve"]),
         type: "Case", icon: "how_to_reg",
         query: vsetkyF + " AND taskIds:(\"t_fa_schvalenie\" OR \"t_fa_riaditel\")",
         nets: [faktura], roles: ["schvalovatel": faktura, "riaditel": faktura],
         headers: stlpceF, uri: uriF],
        [id: "sc_fa_na_zauctovanie", name: i18n("Na zaúčtovanie", ["en": "To post"]),
         type: "Case", icon: "account_balance",
         query: vsetkyF + " AND taskIds:\"t_fa_zauctovanie\"",
         nets: [faktura], roles: ["uctovnik": faktura], headers: stlpceF, uri: uriF],
        [id: "sc_fa_uzavrete", name: i18n("Uzavreté faktúry", ["en": "Closed invoices"]),
         type: "Case", icon: "task_alt",
         // Filtruje sa podla KLUCA moznosti, nie podla popisku: `fa_stav_label` je
         // `enumeration_map`, aby sa stav dal prelozit - a kluc je nezavisly
         // od jazyka aj od preformulovania popisku.
         query: vsetkyF + " AND dataSet.fa_stav_label.textValue:(\"zauctovana\" OR \"zamietnuta\")",
         nets: [faktura], roles: [:], headers: stlpceF, uri: uriF],
        // --- Objednavky ---
        [id: "sc_ob_vsetky", name: i18n("Objednávky", ["en": "Purchase orders"]),
         type: "Case", icon: "shopping_cart",
         query: vsetkyO, nets: [objednavka], roles: [:], headers: stlpceO, uri: uriO],
        [id: "sc_ob_na_schvalenie", name: i18n("Objednávky na schválenie", ["en": "Orders to approve"]),
         type: "Case", icon: "how_to_reg",
         query: vsetkyO + " AND taskIds:(\"t_ob_schvalenie\" OR \"t_ob_riaditel\")",
         nets: [objednavka], roles: ["schvalovatel": objednavka, "riaditel": objednavka],
         headers: stlpceO, uri: uriO],
        [id: "sc_ob_na_objednanie", name: i18n("Schválené na objednanie", ["en": "Approved to order"]),
         type: "Case", icon: "local_shipping",
         query: vsetkyO + " AND taskIds:\"t_ob_objednanie\"",
         nets: [objednavka], roles: [:], headers: stlpceO, uri: uriO],
]

views.each { v ->
    def id = v.id as String
    try {
        def existing = menu_item(id)
        if (existing != null) {
            // Porovnava sa dopyt, allowedNets A nazov vratane prekladov -
            // vsetko ostatne sa da dorovnat na existujucej polozke. Bez nazvu
            // v porovnani by uz nasadena instancia zmeneny nazov nikdy
            // nedostala: polozka tam je s tym istym dopytom, takze by sa vzdy
            // vyhodnotila ako nezmenena.
            def current = getFilterFromMenuItem(existing)
            def currentQuery = ((current?.dataSet?."filter"?.value ?: "") as String)
            def currentNets = ((current?.dataSet?."filter"?.allowedNets ?: []) as List)
                    .collect { it as String } as Set
            def wantNets = (v.nets as List).collect { it as String } as Set
            def currentName = current?.dataSet?."i18n_filter_name"?.value
            def sameName = currentName != null &&
                    (currentName.defaultValue as String) == (v.name.defaultValue as String) &&
                    (currentName.translations ?: [:]) == (v.name.translations ?: [:])
            if (currentQuery == (v.query as String) && currentNets == wantNets && sameName) {
                nastav_zobrazenie(existing, v.nets as List, v.headers)
                // Uzol dorovnaj AJ pri nezmenenej polozke: URI uzly zije
                // Elasticsearch, polozky menu Mongo. Po vymene ES indexu maju
                // uzly nove id, polozka visi na starom a priecinok je PRAZDNY -
                // bez chyby a bez logu. `createOrUpdateMenuItem` to riesi, ale
                // sem sa nedostane, lebo dopyt ani nazov sa nezmenili.
                pripoj_do_uzla(existing, v.uri as String)
                unchanged << id
                return
            }
            // PORADIE JE POVINNE: najprv polozka, potom filter. Naopak to padne
            // na `Could not find Case with id [...]`, lebo `deleteMenuItem` si
            // filter este raz nacita podla id ulozeneho na polozke.
            deleteMenuItem(existing)
            if (current != null) {
                deleteFilter(current)
            }
        }
        def item = createOrUpdateMenuItem(
                id,                 // menu_item_identifier
                v.uri as String,    // URI cesta - musi sedet s uriNodes
                v.type as String,
                v.query as String,
                v.icon as String,
                v.name,             // I18nString - polozka menu vie byt dvojjazycna
                v.nets as List,     // allowedNets - bez toho ziadne stlpce ani "+"
                v.roles as Map,     // allowed_roles: importId -> identifikator siete
                [:]                 // bannedRoles - dourcuje aritu na projektovu
        )
        if (item) { created << id } else { failed << id }
        nastav_zobrazenie(item, v.nets as List, v.headers)
    } catch (Exception e) {
        failed << (id + " (" + e.getClass().simpleName + ": " + e.message + ")")
    }
}

// Vysledok patri do nazvu casu, nie do datoveho pola: po zakladani filtrov sa
// zapis do vlastneho casu neuchova - engine medzitym zakladal ine casy a nas
// outcome zahodil. changeCaseProperty prezije.
def summary = "Menu Schvaľovania – " + (created.size() + unchanged.size()) + "/" + views.size()
if (failed) {
    summary = "CHYBA menu Schvaľovania – nepodarilo sa: " + failed.join(", ")
}
changeCaseProperty("title").about { summary }

document.function:
{ def menuItem, def nets, def headers ->
    // `enable_case_title`  - vypnuty dialog "Vyplnte nazov pripadu" pri "+";
    //                        nazov casu potom da `create` akcia siete.
    // `default_headers`    - predvolene stlpce zoznamu.
    // Ani jedno nie je argument `createOrUpdateMenuItem`.
    if (menuItem == null) return
    def payload = [:]
    if (nets) {
        payload.put("enable_case_title", ["value": false, "type": "boolean"])
        payload.put("case_require_title_in_creation", ["value": false, "type": "boolean"])
    }
    if (headers) {
        payload.put("default_headers", ["value": headers as String, "type": "text"])
    }
    if (payload) {
        setData("view", menuItem, payload)
    }
}

{ def identifier ->
    // `findMenuItem(id)` z ActionDelegate existujucu polozku nenajde (hlada
    // v inom rozsahu), takze by sa pri kazdom spusteni zalozila druha sada.
    def id = ((identifier ?: "") as String).trim()
    if (!id) return null
    def items = findCases { it.processIdentifier.eq("preference_filter_item") }
    return items?.find { ((it.dataSet["menu_item_identifier"]?.value ?: "") as String) == id }
}
